def answer_D(left_is_truth, is_liar):
    inner_true = left_is_truth
    said_Q = (not inner_true) if is_liar else inner_true
    outer_true = said_Q
    final = (not outer_true) if is_liar else outer_true
    return final

for left in [True, False]:
    for liar in [True, False]:
        print("left_is_truth=",left,"liar=",liar,"answer=",answer_D(left,liar))
