import itertools
# Intended reading: 25 squares form a 5x5 block; strokes = full straight lines (rows/cols).
# Min strokes to cover 5x5 block:
best=None
cells=[(r,c) for r in range(5) for c in range(5)]
lines=[('r',r) for r in range(5)]+[('c',c) for c in range(5)]
for k in range(1,6):
    for combo in itertools.combinations(lines,k):
        cov=set()
        for t,i in combo:
            if t=='r': cov|={(i,c) for c in range(5)}
            else: cov|={(r,i) for r in range(5)}
        if cov>=set(cells):
            print("min strokes for 5x5 block =",k); raise SystemExit
print("none")
"}

